-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
local palette = require("hypr_palette") -- generated by palette/generate.py

-- The settings panel's values (quickshell/Settings.qml writes hypr_settings.lua, then reloads),
-- laid over these defaults key by key. pcall: a missing or broken file (a fresh clone, a bad
-- write) leaves the defaults instead of failing the whole config.
local settings = {
    gaps_in = 3, gaps_out = 6, border_size = 2, blur = true, blur_size = 6, animations = true,
    repeat_delay = 600, repeat_rate = 25, sensitivity = 0, natural_scroll = true, tap_to_click = true,
}
do
    local ok, user = pcall(require, "hypr_settings")
    if ok and type(user) == "table" then
        for key, value in pairs(user) do
            if type(value) == type(settings[key]) then settings[key] = value end
        end
    end
end

hl.config({
    general = {
        -- 6px between any two things, screen edges and bar included (owner, 2026-10-15: outer
        -- gaps once the wallpaper went in; the spec had 4 between and 0 at the edges).
        gaps_in  = settings.gaps_in, -- per window edge: two neighbours end up twice this apart
        gaps_out = settings.gaps_out,

        -- 2px border: amber on the focused window, muted on the rest. No dimming.
        border_size = settings.border_size,
        col = {
            active_border   = palette.accent,
            inactive_border = palette.border,
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    -- Sharp and flat: no rounding, no shadow. Blur behind see-through windows (owner, 2026-10-17,
    -- overriding the spec's "no blur, no transparency"): only apps that are transparent get it
    -- (Alacritty 0.9, Vicinae 0.9 with the layer rule below); everything opaque looks as before.
    decoration = {
        rounding       = 0,
        rounding_power = 2,

        -- Change transparency of focused and unfocused windows
        active_opacity   = 1.0,
        inactive_opacity = 1.0,

        shadow = {
            enabled      = false,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        blur = {
            enabled   = settings.blur,
            size      = settings.blur_size,
            passes    = 2,
            vibrancy  = 0.1696,
        },
    },

    animations = {
        enabled = settings.animations,
    },
})

-- Animations: https://wiki.hypr.land/Configuring/Advanced-and-Cool/Animations/
-- Snappy motion (owner, 2026-10-17, replacing the spec's "minimal": only a fade before): windows
-- slide in from the nearest edge and glide when tiling moves them, both on a spring that
-- overshoots a little and settles; workspaces slide 20% while cross-fading. 150-300 ms.
-- speed is in deciseconds. Border colour changes stay instant. Off: Settings > Look > Window fade
-- (animations.enabled).
hl.curve("out", { type = "bezier", points = { {0.16, 1}, {0.3, 1} } })        -- quick start, soft stop
hl.curve("spring", { type = "bezier", points = { {0.34, 1.3}, {0.64, 1} } }) -- past the end, then back
hl.curve("springBack", { type = "bezier", points = { {0.36, 0}, {0.66, -0.3} } }) -- "spring" played backwards
hl.curve("linear", { type = "bezier", points = { {0, 0}, {1, 1} } })
hl.animation({ leaf = "windowsIn",   enabled = true, speed = 3,   bezier = "spring", style = "slide" })
hl.animation({ leaf = "windowsOut",  enabled = true, speed = 3,   bezier = "springBack", style = "slide" }) -- the open, reversed (owner)
hl.animation({ leaf = "windowsMove", enabled = true, speed = 3,   bezier = "spring" })
hl.animation({ leaf = "workspaces",  enabled = true, speed = 2.5, bezier = "out",    style = "slidefade 20%" })
hl.animation({ leaf = "border",      enabled = false })
hl.animation({ leaf = "layers",      enabled = true, speed = 1.5, bezier = "out", style = "fade" })
hl.animation({ leaf = "fade",        enabled = true, speed = 1.5, bezier = "out" })
hl.animation({ leaf = "fadeLayers",  enabled = true, speed = 1.5, bezier = "out" })

